# frozen_string_literal: true

require "rails_helper"

RSpec.describe TimekeepingOwnership, committed_data: true do
  # "`target_user.destroy!` in `app/controllers/api/v1/users_controller.rb` is refused with a clear
  # error once a handoff has begun, in either ownership state."
  # A delete that checks the row while a handoff update is uncommitted must wait and then refuse,
  # or it would delete after the cutoff.
  it "refuses a guarded block that queued behind an uncommitted handoff update once that update commits" do
    updated = Queue.new
    commit = Queue.new
    handoff_pids = Queue.new
    guarded_pids = Queue.new
    ran = false
    handoff = committed_data_thread(handoff_pids) do
      ActiveRecord::Base.transaction do
        described_class.where(id: described_class::SINGLETON_ID).update_all(handoff_step: "close_admission")
        updated << true
        commit.pop
      end
    end
    expect(updated.pop(timeout: 5)).to be(true), "the handoff update never started"

    guarded = committed_data_thread(guarded_pids) do
      described_class.unless_handoff_begun { ran = true }
    end

    begin
      blocked = blocked_by?(guarded_pids.pop(timeout: 5), handoff_pids.pop(timeout: 5))
    ensure
      commit << true
    end

    expect(blocked).to be(true), "the guarded block never waited on the uncommitted handoff update"
    handoff.join(5)
    expect(guarded.join(5)&.value).to be(false)
    expect(ran).to be(false)
  ensure
    commit << true
    [handoff, guarded].compact.each { |thread| thread.join(5) }
    described_class.where(id: described_class::SINGLETON_ID).update_all(handoff_step: nil)
  end
end

